1	// THE TARGET — which pull request a run works on (docs/PRINCIPLES.md). The
2	// executor resolves it once, after the precondition's go and
3	// before code-work, and hands it to both phases; neither phase discovers, chooses
4	// or disposes of a pull request on its own. What this pins is the planner's matrix
5	// over the four outcomes, how a task's open pull requests are recognised, and the
6	// I/O shell's reads and writes against a fake GitHub.
7	
8	import { test } from 'node:test';
9	import assert from 'node:assert/strict';
10	import {
11	  planTarget, taskPullsOf, taskBranchPrefix, mintBranch, targetEnv,
12	  resolveTarget, closeSuperseded, TARGET_MODES,
13	} from '../../src/execute/target.mjs';
14	
15	const TASK = 'claudinite-lifecycle/update';
16	const NOW = new Date('2026-09-04T04:10:00Z');
17	const pull = (number, ref, sha = `sha${number}`) => ({ number, head: { ref, sha }, node_id: `node${number}` });
18	
19	// --- recognising a task's pull requests ---------------------------------------
20	
21	test('a task\'s open pull requests are the ones on its branch prefix, newest first', () => {
22	  const pulls = [
23	    pull(3, 'claudinite/claudinite-lifecycle/update/2026-09-01-aaa'),
