27	  ];
28	  assert.deepEqual(taskPullsOf(pulls, TASK).map((p) => p.number), [5, 3]);
29	  assert.equal(taskBranchPrefix(TASK), 'claudinite/claudinite-lifecycle/update/');
30	});
